-- HD2-Addon: mods/suzuka/eagle110_boost
local settings_policy=(function()
-- Guarded runtime patch for Eagle 110mm uses per Rearm.
local M={}
local function u32(s,o)local a,b,c,d=s:byte(o+1,o+4);return a+b*256+c*65536+d*16777216 end
local function f32(s,o)local ffi=require('ffi');local v=ffi.new('float[1]');ffi.copy(v,s:sub(o+1,o+4),4);return tonumber(v[0])end
local function p32(v)local ffi=require('ffi');local p=ffi.new('uint32_t[1]',v);return ffi.string(p,4)end
function M.new(api,spec)
 local target=spec.target_uses or 3
 assert(target==2 or target==3 or target==4 or target==5,'invalid_target_uses')
 local applied='APPLIED_USES_'..target
 local s={status='IDLE',writes=0,checks=0,lease=nil}
 local function buffer()return api.pointer(api.read(spec.game+spec.settings_buffer_rva,8))end
 local function locate()
  local base=buffer();if not base then return nil,'WAITING_FOR_SETTINGS_BUFFER' end
  local src=api.read_blob(base,spec.settings_size);if not src then return nil,'SETTINGS_BUFFER_UNREADABLE' end
  local groups=u32(src,0);if groups<1 or groups>32 then return nil,'SETTINGS_GROUP_COUNT_INVALID' end
  local off,found=4,nil
  for _=1,groups do
   if u32(src,off)~=0x444c444c or u32(src,off+4)~=1 or u32(src,off+8)~=0x30eb6399 then return nil,'SETTINGS_HEADER_MISMATCH' end
   local root=off+24;local finish=root+u32(src,off+12);local count=u32(src,root+8)
   local items=api.pointer(src:sub(root+1,root+8));if not items or count>148 or finish>#src then return nil,'SETTINGS_BOUNDS_INVALID' end
   local start=items-base;if start<root+16 or start+count*spec.record_size>finish then return nil,'SETTINGS_RECORD_BOUNDS_INVALID' end
   for i=0,count-1 do local ro=start+i*spec.record_size
    if u32(src,ro+4)==spec.id then if found then return nil,'DUPLICATE_ID' end;found={base=base,address=base+ro,row=src:sub(ro+1,ro+spec.record_size)} end
   end
   off=finish
  end
  if off~=#src then return nil,'SETTINGS_SIZE_MISMATCH' end
  if not found then return nil,'ID_NOT_FOUND' end;return found
 end
 function s:start()self.status='SCANNING';self.writes=0;self.checks=0;self.lease=nil end
 function s:step()
  if self.status==applied then self.checks=self.checks+1;if self.checks%300==0 then local l=locate();if not l or l.address~=self.address or api.read(l.address+spec.use_offset,4)~=p32(target) then self.status='APPLIED_RECORD_CHANGED_RESTART_REQUIRED' end end;return end
  if self.status~='SCANNING' and self.status~='WAITING_FOR_SETTINGS_BUFFER' and self.status~='SETTINGS_BUFFER_UNREADABLE' then return end
  local l,err=locate();if not l then self.status=err;return end
  local row=l.row;local uses=u32(row,spec.use_offset);local cooldown=f32(row,spec.cooldown_offset);local typ=u32(row,0)
  if typ~=140 or uses~=3 or cooldown~=15.0 then self.status=string.format('FINGERPRINT_MISMATCH_TYPE_%u_USES_%u_COOLDOWN_%.1f',typ,uses,cooldown);return end
  if buffer()~=l.base or api.read(l.address,spec.record_size)~=row then self.status='CONTEXT_CHANGED_NO_WRITE';return end
  self.address=l.address
  if target==3 then self.status=applied;return end
  local ok,detail=api.write(l.address+spec.use_offset,p32(target))
  if not ok or api.read(l.address+spec.use_offset,4)~=p32(target) then self.status='WRITE_FAILED_OR_READBACK_MISMATCH';self.error=tostring(detail);return end
  self.lease={base=l.base,address=l.address,original=row};self.writes=1;self.status=applied
 end
 function s:stop()local l=self.lease;if not l then return end;if buffer()==l.base and api.read(l.address+spec.use_offset,4)==p32(target) then local ok=api.write(l.address+spec.use_offset,p32(3));if ok and api.read(l.address,spec.record_size)==l.original then self.status='RESTORED_ON_SHUTDOWN';self.lease=nil;return end end;self.status='RESTORE_NOT_CONFIRMED' end
 return s
end
return M

end)()
local component_policy=(function()
-- Guarded single-record component patch with complete table/record identity checks.
local M={}
function M.new(api,spec)
    assert(#spec.map%16==0 and #spec.original==spec.record_size)
    local target=spec.original
    local last=0
    for _,edit in ipairs(spec.edits) do
        local finish=edit.offset+#edit.bytes
        assert(edit.offset>=last and finish<=spec.record_size and #edit.bytes>0)
        edit.before=spec.original:sub(edit.offset+1,finish)
        target=target:sub(1,edit.offset)..edit.bytes..target:sub(finish+1)
        last=finish
    end
    local s={status='IDLE',writes=0,checks=0,retries=0,lease=nil}
    local function pointer(at)return api.pointer(api.read(at,8))end
    local function owner()return pointer(spec.game+spec.owner_rva)end
    local function map_matches(at)
        if not at then return false end
        local p=spec.probe_offset
        if api.read(at+p,32)~=spec.map:sub(p+1,p+32) then return false end
        for i=0,#spec.map-1,2048 do
            local chunk=spec.map:sub(i+1,i+2048)
            if api.read(at+i,#chunk)~=chunk then return false end
        end
        return true
    end
    local function context(l)
        return owner()==l.owner and pointer(l.slot)==l.table and map_matches(l.table)
    end
    function s:start()
        self.status='SCANNING';self.slot_index=0;self.matches={};self.current_owner=nil
        self.writes=0;self.checks=0;self.retries=0;self.lease=nil;self.error=nil
    end
    local function write_edits(self,lease,baseline,restore)
        local expected=baseline
        for _,edit in ipairs(spec.edits) do
            if not context(lease) or api.read(lease.record,spec.record_size)~=expected then return false end
            local bytes=restore and edit.before or edit.bytes
            local ok=api.write(lease.record+edit.offset,bytes)
            expected=expected:sub(1,edit.offset)..bytes..expected:sub(edit.offset+#bytes+1)
            if not ok or api.read(lease.record,spec.record_size)~=expected then return false end
        end
        return true
    end
    local function apply(self,who,hit)
        local record=hit.table+#spec.map+spec.record_index*spec.record_size
        local row=api.read(record,spec.record_size)
        if row~=spec.original then
            self.status=row==target and 'PREEXISTING_MODIFICATION_NOT_OWNED' or 'TEMPLATE_MISMATCH_NO_WRITE'
            return
        end
        local lease={owner=who,slot=hit.slot,table=hit.table,record=record}
        if not context(lease) or api.read(record,spec.record_size)~=spec.original then
            self.status='CONTEXT_CHANGED_NO_WRITE';return
        end
        self.lease=lease
        if not write_edits(self,lease,spec.original,false) or api.read(record,spec.record_size)~=target then
            self.status='WRITE_FAILED_OR_READBACK_MISMATCH'
            local after=api.read(record,spec.record_size)
            local owned=after~=nil
            if owned then
                for i=1,spec.record_size do
                    local b=after:byte(i)
                    if b~=spec.original:byte(i) and b~=target:byte(i) then owned=false;break end
                end
            end
            if owned and context(lease) then write_edits(self,lease,after,true) end
            if api.read(record,spec.record_size)==spec.original then self.lease=nil end
            return
        end
        self.writes=#spec.edits;self.status='APPLIED_'..spec.label
    end
    function s:step()
        if self.status=='APPLIED_'..spec.label then
            self.checks=self.checks+1
            if self.checks%300==0 and (not context(self.lease)
                or api.read(self.lease.record,spec.record_size)~=target) then
                self.status='APPLIED_RECORD_CHANGED_RESTART_REQUIRED'
            end
            return
        end
        if self.status=='WAITING_FOR_ENTITY_MANAGER' then self.status='SCANNING' end
        if self.status=='NO_MATCH_RETRYING' then
            self.delay=self.delay-1;if self.delay>0 then return end
            self.status='SCANNING';self.slot_index=0;self.matches={}
        end
        if self.status~='SCANNING' then return end
        local who=owner();if not who then self.status='WAITING_FOR_ENTITY_MANAGER';return end
        if self.current_owner~=who then self.current_owner=who;self.slot_index=0;self.matches={} end
        local count=(spec.scan_end-spec.scan_begin)/8
        for _=1,32 do
            if self.slot_index>=count then
                if #self.matches==1 then apply(self,who,self.matches[1]);return end
                self.status='NO_MATCH_RETRYING';self.delay=300;self.retries=self.retries+1;return
            end
            local slot=who+spec.scan_begin+self.slot_index*8;self.slot_index=self.slot_index+1
            local at=pointer(slot)
            if at and map_matches(at) then
                self.matches[#self.matches+1]={slot=slot,table=at}
                if #self.matches>1 then self.status='AMBIGUOUS_COMPONENT_TABLES_NO_WRITE';return end
            end
        end
    end
    function s:stop()
        local l=self.lease;if not l then return end
        if context(l) and api.read(l.record,spec.record_size)==target
            and write_edits(self,l,target,true)
            and api.read(l.record,spec.record_size)==spec.original then
            self.status='RESTORED_ON_SHUTDOWN';self.lease=nil;return
        end
        self.status='RESTORE_NOT_CONFIRMED'
    end
    return s
end
return M

end)()
local create_api=(function()
-- Windows API adapter for a single, guarded GL-28 capacity change.
return function()
    local ffi=require('ffi')
    assert(ffi.os=='Windows' and ffi.abi('64bit'),'windows_x64_required')
    ffi.cdef[[
        void *GetModuleHandleA(const char *);
        uint32_t GetModuleFileNameW(void *,uint16_t *,uint32_t);
        void *GetCurrentProcess(void);
        int ReadProcessMemory(void *,const void *,void *,size_t,size_t *);
        int WriteProcessMemory(void *,void *,const void *,size_t,size_t *);
        size_t VirtualQuery(const void *,void *,size_t);
        int VirtualProtect(void *,size_t,uint32_t,uint32_t *);
        uint32_t GetLastError(void);
        void *CreateFileW(const uint16_t *,uint32_t,uint32_t,void *,uint32_t,uint32_t,void *);
        int ReadFile(void *,void *,uint32_t,uint32_t *,void *);
        int CloseHandle(void *);
        int32_t BCryptOpenAlgorithmProvider(void **,const uint16_t *,const uint16_t *,uint32_t);
        int32_t BCryptCreateHash(void *,void **,void *,uint32_t,const void *,uint32_t,uint32_t);
        int32_t BCryptHashData(void *,const void *,uint32_t,uint32_t);
        int32_t BCryptFinishHash(void *,void *,uint32_t,uint32_t);
        int32_t BCryptDestroyHash(void *);
        int32_t BCryptCloseAlgorithmProvider(void *,uint32_t);
        typedef struct { void *base; void *allocation; uint32_t protection0;
            uint16_t partition; uint16_t reserved; size_t size;
            uint32_t state; uint32_t protection; uint32_t kind; } SuzukaCapacityRegion;
    ]]
    local k,b=ffi.load('kernel32'),ffi.load('bcrypt')
    local process=k.GetCurrentProcess()
    local api={}
    local scan_buffer=ffi.new('uint8_t[262144]')
    local scan_count=ffi.new('size_t[1]')
    local scan_address=tonumber(ffi.cast('uintptr_t',scan_buffer))
    function api.excluded(address,size)
        return address<scan_address+262144 and address+size>scan_address
    end
    function api.query(address)
        if address>=0x800000000000 then return nil,'end' end
        local info=ffi.new('SuzukaCapacityRegion[1]')
        if k.VirtualQuery(ffi.cast('void *',address),info,ffi.sizeof(info[0]))~=ffi.sizeof(info[0]) then
            return nil,k.GetLastError()==87 and 'end' or 'query_failed'
        end
        local r=info[0]
        local p=tonumber(r.protection)%256
        local kind=tonumber(r.kind)
        return {base=tonumber(ffi.cast('uintptr_t',r.base)),allocation=tonumber(ffi.cast('uintptr_t',r.allocation)),size=tonumber(r.size),
            protection=tonumber(r.protection),
            readable=r.state==0x1000 and (kind==0x20000 or kind==0x40000)
                and (p==2 or p==4 or p==8 or p==32 or p==64 or p==128)
                and tonumber(r.protection)<256,kind=kind}
    end
    function api.read_blob(address,size)
        if type(size)~='number' or size<=0 or size>262144 or api.excluded(address,size) then return nil end
        local r=api.query(address)
        if not r or not r.readable or address<r.base or address+size>r.base+r.size then return nil end
        if k.ReadProcessMemory(process,ffi.cast('const void *',address),scan_buffer,size,scan_count)==0
            or tonumber(scan_count[0])~=size then return nil end
        return ffi.string(scan_buffer,size)
    end
    -- Read-only bulk access for committed module-image pages. General memory
    -- scanners intentionally exclude MEM_IMAGE; layout migration needs to
    -- inspect game.dll's own global-pointer slots without enabling writes.
    function api.read_module(address,size)
        if type(size)~='number' or size<=0 or size>262144 or api.excluded(address,size) then return nil end
        local r=api.query(address)
        if not r or r.kind~=0x1000000 or address<r.base or address+size>r.base+r.size
            or r.protection>=256 then return nil end
        local p=r.protection%256
        if p~=2 and p~=4 and p~=8 and p~=32 and p~=64 and p~=128 then return nil end
        if k.ReadProcessMemory(process,ffi.cast('const void *',address),scan_buffer,size,scan_count)==0
            or tonumber(scan_count[0])~=size then return nil end
        return ffi.string(scan_buffer,size)
    end
    function api.module(name)
        local p=k.GetModuleHandleA(name)
        if p==nil or p==ffi.NULL then return nil end
        return tonumber(ffi.cast('uintptr_t',p))
    end
    function api.pointer(bytes)
        if not bytes or #bytes~=8 then return nil end
        local p=ffi.new('uint64_t[1]')
        ffi.copy(p,bytes,8)
        if p[0]<65536 or p[0]>=0x800000000000 then return nil end
        return tonumber(p[0])
    end
    local function region(address,size)
        if type(address)~='number' or type(size)~='number' or size<=0
            or address<65536 or address+size>=0x800000000000 then return nil end
        local info=ffi.new('SuzukaCapacityRegion[1]')
        if k.VirtualQuery(ffi.cast('void *',address),info,ffi.sizeof(info[0]))~=ffi.sizeof(info[0]) then return nil end
        local r=info[0]
        local base=tonumber(ffi.cast('uintptr_t',r.base))
        local protection=tonumber(r.protection)
        if r.state~=0x1000 or address<base or address+size>base+tonumber(r.size)
            or (r.kind~=0x20000 and r.kind~=0x40000 and r.kind~=0x1000000)
            or protection>=256 then return nil end
        return protection,tonumber(r.kind)
    end
    function api.read(address,size)
        if size>4096 or not region(address,size) then return nil end
        local out,count=ffi.new('uint8_t[?]',size),ffi.new('size_t[1]')
        if k.ReadProcessMemory(process,ffi.cast('const void *',address),out,size,count)==0
            or tonumber(count[0])~=size then return nil end
        return ffi.string(out,size)
    end
    function api.write(address,bytes)
        if type(bytes)~='string' or (#bytes~=1 and #bytes~=4 and #bytes~=8 and #bytes~=12
            and #bytes~=16 and #bytes~=24 and #bytes~=268) then
            return false,'invalid_size'
        end
        local protection,kind=region(address,#bytes)
        -- PAGE_WRITECOPY (8) is a non-executable data page used by some
        -- runtime resource snapshots. Allow it with the same guarded
        -- VirtualProtect/write/readback path as PAGE_READONLY.
        if (protection~=2 and protection~=4 and protection~=8) or kind==0x1000000 then
            return false,'not_plain_data_page'
        end
        local before=api.read(address,#bytes)
        if not before then return false,'before_read_failed' end
        local changed=false
        local old=ffi.new('uint32_t[1]')
        if protection~=4 then
            if k.VirtualProtect(ffi.cast('void *',address),#bytes,4,old)==0 then
                return false,'make_writable_failed_'..tonumber(k.GetLastError())
            end
            changed=true
        end
        local count=ffi.new('size_t[1]')
        local ok=k.WriteProcessMemory(process,ffi.cast('void *',address),bytes,#bytes,count)~=0
            and tonumber(count[0])==#bytes
        local write_error=ok and 0 or tonumber(k.GetLastError())
        local restored=true
        if changed then
            local ignored=ffi.new('uint32_t[1]')
            restored=k.VirtualProtect(ffi.cast('void *',address),#bytes,old[0],ignored)~=0
        end
        local after=api.read(address,#bytes)
        return ok and restored and after==bytes,
            string.format('written=%d error=%d restored=%s readback=%s',
                tonumber(count[0]),write_error,tostring(restored),tostring(after==bytes))
    end
    function api.module_hash(address)
        local cached=rawget(_G,'SuzukaVerifiedGameDllHash')
        if type(cached)=='table' and cached.address==address
            and type(cached.sha256)=='string' and #cached.sha256==64 then
            return cached.sha256
        end
        local path=ffi.new('uint16_t[32768]')
        local n=k.GetModuleFileNameW(ffi.cast('void *',address),path,32768)
        assert(n>0 and n<32768,'game_dll_path_unavailable')
        local file=k.CreateFileW(path,0x80000000,7,nil,3,0x08000000,nil)
        assert(file~=ffi.cast('void *',-1),'game_dll_file_unavailable')
        local algorithm,hash=ffi.new('void *[1]'),ffi.new('void *[1]')
        local ok,result=pcall(function()
            local name=ffi.new('uint16_t[7]',{83,72,65,50,53,54,0})
            assert(b.BCryptOpenAlgorithmProvider(algorithm,name,nil,0)==0,'sha256_provider')
            assert(b.BCryptCreateHash(algorithm[0],hash,nil,0,nil,0,0)==0,'sha256_create')
            local chunk,count=ffi.new('uint8_t[65536]'),ffi.new('uint32_t[1]')
            local total=0
            while true do
                assert(k.ReadFile(file,chunk,65536,count,nil)~=0,'game_dll_read')
                if count[0]==0 then break end
                total=total+tonumber(count[0])
                assert(total<=64*1024*1024,'game_dll_too_large')
                assert(b.BCryptHashData(hash[0],chunk,count[0],0)==0,'sha256_update')
            end
            local digest,parts=ffi.new('uint8_t[32]'),{}
            assert(b.BCryptFinishHash(hash[0],digest,32,0)==0,'sha256_finish')
            for i=0,31 do parts[#parts+1]=string.format('%02x',digest[i]) end
            return table.concat(parts)
        end)
        if hash[0]~=nil then b.BCryptDestroyHash(hash[0]) end
        if algorithm[0]~=nil then b.BCryptCloseAlgorithmProvider(algorithm[0],0) end
        k.CloseHandle(file)
        assert(ok,result)
        rawset(_G,'SuzukaVerifiedGameDllHash',{address=address,sha256=result})
        return result
    end
    return api
end

end)()
local function unhex(s)return(s:gsub("..",function(x)return string.char(tonumber(x,16))end))end
local module_sha256='2e2c3b7c2500646dadd5f2b4c6e0504dbb7e7896139f64cddc0d1813c718f51e'
local owner_rva=0x3326B90
local labels={'USES','EAGLE_TIMING','RIGHT_POD','LEFT_POD'}
local settings_spec={settings_buffer_rva=0x348E8F8,settings_size=80280,record_size=400,id=1979913877,use_offset=0x50,cooldown_offset=0x68}
settings_spec.target_uses=3
local component_specs={
{label='FIRE_WINDOW_4_INTERVAL_0_33',scan_begin=0xf10000,scan_end=0xf13000,record_size=152,record_index=9,probe_offset=0,map=unhex(''),original=unhex(''),edits={{offset=40,bytes=unhex('00008040')},{offset=44,bytes=unhex('c3f5a83e')}}},
{label='RIGHT_POD_6',scan_begin=0xf10000,scan_end=0xf13000,record_size=160,record_index=183,probe_offset=32,map=unhex(''),original=unhex(''),edits={{offset=136,bytes=unhex('06000000')}}},
{label='LEFT_POD_6',scan_begin=0xf10000,scan_end=0xf13000,record_size=160,record_index=185,probe_offset=32,map=unhex(''),original=unhex(''),edits={{offset=136,bytes=unhex('06000000')}}},
}
if rawget(_G,'SuzukaEagle110Boost') then return end
local state={version='2.3.1',status='INITIALIZING',policies={}}
rawset(_G,'SuzukaEagle110Boost',state)
local loader=rawget(_G,'CowboyBingusModLoader')

local function report()
    local ok,err=pcall(function()
        local file=assert(loader.open_log('SuzukaEagle110Boost.log'),'log_unavailable')
        file:write('Suzuka‘s Eagle 110mm enhancement '..state.version..'\nSTATUS='..state.status..'\n')
        file:write('TARGET=base uses 3 -> '..(settings_spec.target_uses or 3)..'; right/left magazines 3 -> 6; fire_duration 2 -> 4; bomb_interval 0.50 -> 0.33\n')
        if state.sha then file:write('GAME_SHA256='..state.sha..'\n') end
        if state.owner_rva then file:write(string.format('OWNER_RVA=0x%X\n',state.owner_rva)) end
        if state.settings_rva then file:write(string.format('SETTINGS_RVA=0x%X\n',state.settings_rva)) end
        for i,policy in ipairs(state.policies) do
            file:write(labels[i]..'='..policy.status..' writes='..policy.writes..'\n')
            if policy.error then file:write(labels[i]..'_ERROR='..tostring(policy.error)..'\n') end
        end
        if state.error then file:write('ERROR='..state.error..'\n') end
        file:close()
    end)
    if not ok then state.log_error=tostring(err);print('SuzukaEagle110Boost log error: '..state.log_error) end
end

local ok,err=pcall(function()
    assert(loader and loader.api==1,'Bingus Shared Loader API 1 required')
    local api=create_api()
    local game=assert(api.module('game.dll'),'game.dll unavailable')
    state.sha=api.module_hash(game)
    assert(state.sha==module_sha256,'unsupported_game_dll_no_write')
    state.owner_rva=owner_rva
    state.settings_rva=settings_spec.settings_buffer_rva
    settings_spec.game=game
    state.policies={settings_policy.new(api,settings_spec)}
    for _,spec in ipairs(component_specs) do
        spec.game=game
        spec.owner_rva=owner_rva
        state.policies[#state.policies+1]=component_policy.new(api,spec)
    end
    for _,policy in ipairs(state.policies) do policy:start() end
    state.status='APPLYING'

    local original_update=assert(rawget(_G,'update'),'update unavailable')
    local original_shutdown=rawget(_G,'shutdown')
    local last=''
    local function pack(...) return {n=select('#',...),...} end
    local function restore()
        local clean=true
        for i=#state.policies,1,-1 do
            local good,problem=pcall(function()state.policies[i]:stop()end)
            if not good then
                clean=false
                state.error=(state.error or '')..' restore_'..labels[i]..'='..tostring(problem)
            elseif state.policies[i].lease then clean=false end
        end
        return clean
    end
    _G.update=function(...)
        local result=pack(original_update(...))
        if state.status=='APPLYING' or state.status=='APPLIED_ALL' then
            local good,problem=pcall(function()
                local all=true
                for i,policy in ipairs(state.policies) do
                    policy:step()
                    local current=policy.status
                    if not current:find('^APPLIED_') then
                        all=false
                        local pending=current=='SCANNING' or current=='WAITING_FOR_SETTINGS_BUFFER'
                            or current=='SETTINGS_BUFFER_UNREADABLE'
                            or current=='WAITING_FOR_ENTITY_MANAGER' or current=='NO_MATCH_RETRYING'
                        if not pending then
                            state.status='POLICY_FAILED_ROLLING_BACK'
                            state.error=labels[i]..'='..current
                            state.status=restore() and 'DISABLED_POLICY_FAILED_RESTORED'
                                or 'DISABLED_RESTORE_UNCONFIRMED'
                            break
                        end
                    end
                end
                if state.status=='APPLYING' or state.status=='APPLIED_ALL' then
                    state.status=all and 'APPLIED_ALL' or 'APPLYING'
                end
            end)
            if not good then
                state.error=tostring(problem)
                state.status=restore() and 'DISABLED_RUNTIME_ERROR_RESTORED'
                    or 'DISABLED_RESTORE_UNCONFIRMED'
            end
        end
        local now=state.status
        for _,policy in ipairs(state.policies) do now=now..'|'..policy.status end
        if now~=last then last=now;report() end
        return unpack(result,1,result.n)
    end
    _G.shutdown=function(...)
        restore()
        report()
        if original_shutdown then return original_shutdown(...) end
    end
end)
if not ok then state.status='DISABLED_NO_WRITE';state.error=tostring(err) end
report()
